import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Agent Course 学习笔记","description":"awesome-generative-ai-guide 课程笔记：Brain/Perception/Action 三组件模型、多 Agent 交互类型与评估基准清单（实现机制见 Learn LLM 第 13 章）。","frontmatter":{"title":"Agent Course 学习笔记","description":"awesome-generative-ai-guide 课程笔记：Brain/Perception/Action 三组件模型、多 Agent 交互类型与评估基准清单（实现机制见 Learn LLM 第 13 章）。","domain":"tech","tags":["tech","course-notes","legacy","agent"],"navOrder":83,"topicId":"course-notes-agent-course","layer":"appendix","status":"legacy","nodeType":"resource","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"tech/appendices/course-notes/agent-course.md","filePath":"tech/appendices/course-notes/agent-course.md","lastUpdated":1791115887000}'),s={name:"tech/appendices/course-notes/agent-course.md"};function o(d,e,i,l,g,h){return r(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="agent-course-free-学习笔记" tabindex="-1">Agent Course (Free) 学习笔记 <a class="header-anchor" href="#agent-course-free-学习笔记" aria-label="Permalink to &quot;Agent Course (Free) 学习笔记&quot;">​</a></h1><blockquote><p>来源: <a href="https://github.com/aishwaryanr/awesome-generative-ai-guide" target="_blank" rel="noreferrer">awesome-generative-ai-guide</a> - Applied LLMs Mastery &amp; Agents 101 学习日期: 2026-04-12 | 实现机制见 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 第 13 章（Agent）</p></blockquote><h2 id="一、agent-核心理论框架" tabindex="-1">一、Agent 核心理论框架 <a class="header-anchor" href="#一、agent-核心理论框架" aria-label="Permalink to &quot;一、Agent 核心理论框架&quot;">​</a></h2><h3 id="agent-三组件模型" tabindex="-1">Agent 三组件模型 <a class="header-anchor" href="#agent-三组件模型" aria-label="Permalink to &quot;Agent 三组件模型&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  Agent                   │</span></span>
<span class="line"><span>├─────────────┬──────────────┬────────────┤</span></span>
<span class="line"><span>│   Brain    │  Perception  │   Action   │</span></span>
<span class="line"><span>│ (大脑)     │   (感知)      │   (行动)   │</span></span>
<span class="line"><span>└─────────────┴──────────────┴────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>说明</th></tr></thead><tbody><tr><td><strong>Brain</strong></td><td>中央控制器</td><td>存储信息、处理思考、做出决策</td></tr><tr><td><strong>Perception</strong></td><td>感知模块</td><td>解析外部环境的各种感官输入</td></tr><tr><td><strong>Action</strong></td><td>行动模块</td><td>使用工具执行任务并影响周围环境</td></tr></tbody></table><h3 id="实用四组件模型" tabindex="-1">实用四组件模型 <a class="header-anchor" href="#实用四组件模型" aria-label="Permalink to &quot;实用四组件模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>职责</th><th>示例</th></tr></thead><tbody><tr><td><strong>Agent Core</strong></td><td>核心决策</td><td>目标定义、工具指令、行为模式</td></tr><tr><td><strong>Memory Module</strong></td><td>记忆存储</td><td>短期记忆（当前对话）+ 长期记忆（历史积累）</td></tr><tr><td><strong>Tools</strong></td><td>工具调用</td><td>RAG、代码解释器、搜索 API</td></tr><tr><td><strong>Planning Module</strong></td><td>规划</td><td>任务分解（Task Decomposition）、反思批判（Reflection）</td></tr></tbody></table><p>Memory 检索机制：语义相似性（embedding 向量检索）、重要性加权、时序性（最近优先）、领域自定义指标。</p><h2 id="二、单-agent-与多-agent" tabindex="-1">二、单 Agent 与多 Agent <a class="header-anchor" href="#二、单-agent-与多-agent" aria-label="Permalink to &quot;二、单 Agent 与多 Agent&quot;">​</a></h2><p>单 Agent 孤立运行，缺乏协作、社会学习与多轮反馈能力。多智能体系统（MAS）的优势：分工协作、集体决策、任务分解。交互类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Cooperative（合作）</strong></td><td>Agent 协同追求共同目标</td><td>任务分解流水线</td></tr><tr><td><strong>Adversarial（对抗）</strong></td><td>Agent 通过博弈优化</td><td>代码评审、质量把控</td></tr></tbody></table><h2 id="三、agent-评估基准" tabindex="-1">三、Agent 评估基准 <a class="header-anchor" href="#三、agent-评估基准" aria-label="Permalink to &quot;三、Agent 评估基准&quot;">​</a></h2><table tabindex="0"><thead><tr><th>基准</th><th>用途</th><th>链接</th></tr></thead><tbody><tr><td>AgentBench</td><td>综合评估</td><td><a href="https://github.com/THUDM/AgentBench" target="_blank" rel="noreferrer">THUDM/AgentBench</a></td></tr><tr><td>ToolBench</td><td>工具调用能力</td><td><a href="https://arxiv.org/abs/2305.16504" target="_blank" rel="noreferrer">Paper</a></td></tr><tr><td>ClemBench</td><td>多样化任务</td><td><a href="https://arxiv.org/abs/2305.13455" target="_blank" rel="noreferrer">Paper</a></td></tr></tbody></table><p>评估方法学的 canonical 在 <a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals.zenheart.site</a>。</p><h2 id="四、推荐学习路径-5-day-roadmap" tabindex="-1">四、推荐学习路径（5-Day Roadmap） <a class="header-anchor" href="#四、推荐学习路径-5-day-roadmap" aria-label="Permalink to &quot;四、推荐学习路径（5-Day Roadmap）&quot;">​</a></h2><ul><li><strong>Day 1-2 基础概念</strong>: <a href="https://deepchecks.com/glossary/llm-agents/" target="_blank" rel="noreferrer">LLM Agents Glossary</a> | <a href="https://developer.nvidia.com/blog/introduction-to-llm-agents/" target="_blank" rel="noreferrer">Intro to LLM Agents - Nvidia</a></li><li><strong>Day 3-4 核心框架</strong>: <a href="https://github.com/aishwaryanr/awesome-generative-ai-guide/blob/main/resources/agents_101_guide.md" target="_blank" rel="noreferrer">Agents 101 Guide</a> | <a href="https://lilianweng.github.io/posts/2023-06-23-agent/" target="_blank" rel="noreferrer">LLM Powered Autonomous Agents - Lilian Weng</a></li><li><strong>Day 5 实战构建</strong>: <a href="https://www.deeplearning.ai/short-courses/ai-agents-in-langgraph/" target="_blank" rel="noreferrer">AI Agents in LangGraph - Deeplearning.AI</a></li></ul><h2 id="五、与主线文档的关系" tabindex="-1">五、与主线文档的关系 <a class="header-anchor" href="#五、与主线文档的关系" aria-label="Permalink to &quot;五、与主线文档的关系&quot;">​</a></h2><p>本笔记的三组件/四组件框架与多 Agent 交互模式已展开为主线 <a href="/tech/06-agent-systems/agent-runtime.html">Agent 运行时</a>、<a href="/tech/06-agent-systems/design-patterns.html">Agent 设计模式</a>与<a href="/tech/06-agent-systems/multi-agent.html">多 Agent 系统</a>；本页保留为课程出处与外部资源索引。</p><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to &quot;相关资源&quot;">​</a></h2><ul><li><a href="https://github.com/hyp1231/awesome-llm-powered-agent" target="_blank" rel="noreferrer">awesome-llm-powered-agent</a> - Agent 研究汇总</li><li><a href="https://github.com/e2b-dev/awesome-ai-agents" target="_blank" rel="noreferrer">awesome-ai-agents</a> - AI Agent 工具列表</li><li><a href="https://github.com/aishwaryanr/awesome-generative-ai-guide/blob/main/free_courses/Applied_LLMs_Mastery_2024" target="_blank" rel="noreferrer">Applied LLMs Mastery 2024</a> - 完整课程</li></ul>`,21)])])}const f=t(s,[["render",o]]);export{m as __pageData,f as default};
